    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            queue = deque([(r, c)])
            seen.add((r, c))
            cells = []
            touches_edge = False
            while queue:
                y, x = queue.popleft()
                cells.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
